		/** 
		 * Tests creating a new Metric.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Metric");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Metric" );

			try {            
				Metric entity = MetricService.getMetricInstance().createMetric( generateNewEntity() );
				thePrimaryKey = entity.getMetricId();
				LOGGER.info( "-- Successfully created a Metric with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Metric. 
		 */
		public Metric testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Metric" );

			Metric entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Metric with primary key" );
			msg.append( thePrimaryKey );
			
			MetricFetchOneSummary fetchOneSummary = new MetricFetchOneSummary( thePrimaryKey );

			try {
				entity = MetricService.getMetricInstance().getMetric( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Metric " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Metric.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Metric." );

			StringBuilder msg = new StringBuilder( "Failed to update a Metric : " );        
			Metric entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Metric." );

				// for use later on...
				thePrimaryKey = entity.getMetricId();

				MetricService proxy = MetricService.getMetricInstance();            
				proxy.updateMetric( entity );   

				LOGGER.info( "-- Successfully saved Metric - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Metric.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Metric." );

			try{
			    Metric entity = testRead(); 
				MetricService.getMetricInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Metric with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Metric with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Metrics.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Metrics:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Metric : " );        
			List<Metric> collection  = null;

			try {
				// call the static get method on the MetricService
				collection = MetricService.getMetricInstance().getAllMetric();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Metric entity = null;            
					Iterator<Metric> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getMetricId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

